var b="url",c="operation-_lading_-_detail.html",d="generationDate",e=new Date(1770712627535.52),f="defaultAdaptiveView",g="name",h="",i="size",j="width",k=428,l="height",m=926,n="adaptiveViews",o="sketchKeys",p="s0",q="variables",r="OnLoadVariable",s="v",t="a",u="nz",v="tash1",w="dymali",x="dykhaz",y="mopay",z="mopayt",A="nz2",B="currentTime",C="SourceForm",D="lg",E="vi",F="check",G="san",H="ba",I="loginv",J="inpa",K="page",L="packageId",M="2516b4d54bc449959504e8496d96fe8a",N="type",O="Axure:Page",P="Operation- lading - detail",Q="notes",R="annotations",S="fn",T="1",U="ownerId",V="747a1fe6f1f643c4b5335a0986fe652e",W="label",X="(Shape)",Y="Note",Z="<p><span>اسکن اقلامی که قرار است توسط مسئول بارگیری در خودرو قرار بگیرند در قسمت &quot;خودرو&quot; قابل مشاهده و اسکن است</span></p>",ba="2",bb="db371800ac85469b858269ab00e6a9c9",bc="Header 3",bd="<p><span>1. </span><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">پک‌های سبز (تکمیل)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">معنای وضعیت: تمامی اقلام این پک در ماشین قرار گرفته‌اند.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">لیبل نمایشی: تکمیل</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">2. پک‌های زرد (در حال بارگیری)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">معنای وضعیت: عملیات بارگیری این پک آغاز شده و در جریان است.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">لیبل نمایشی: در حال بارگیری</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">3. پک‌های سفید (بارگیری نشده)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">معنای وضعیت: هنوز هیچ یک از اقلام این پک در ماشین قرار نگرفته‌اند. این پک‌ها آماده‌ی تخصیص و شروع بارگیری هستند.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">4. پک‌های قرمز (کسری)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">معنای وضعیت: برای این پک، درخواست یا برگه‌ی کسری صادر شده است.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#8C1818;\">مکانیزم تغییر رنگ: تغییر رنگ به قرمز باید به‌صورت خودکار و بلافاصله پس از صدور کسری برای پک اتفاق بیفتد</span><span>.</span></p><p><span><br></span></p><p><span>--------------------------------------</span></p><p><span><br></span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">سیستم صدور کسری اقلام </span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">۱. مجوز صدور کسری</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">کسری اقلام فقط می‌تواند برای پک‌های با وضعیت در حال بارگیری (زرد) و بارگیری نشده (سفید) صادر شود.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">پک‌های با وضعیت تکمیل (سبز) نمی‌توانند شامل کسری شوند.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">۲. تعریف فرآیند کسری (نسخه قدیم - منسوخ)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">در مدل جاری: صدور کسری به معنی ایجاد خودکار یک سفارش جدید از مانده بارگیری‌نشده کالا برای مشتری بود. این سفارش جدید در مرحله &quot;تامین&quot; ایجاد می‌شد.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">۳. اصلاحیه و فرآیند آتی</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">بر اساس جلسات اخیر، ایجاد سفارش جدید در مرحله &quot;تامین&quot; به عنوان نتیجه صدور کسری، کاملاً حذف خواهد شد.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">فرآیند جدید: صدور کسری صرفاً باید بر اساس مانده سفارش در مراحل &quot;تکمیل&quot; انجام شود.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#4105C6;\">به عبارت دیگر: سیستم هنگام صدور کسری باید تنها موجودی و مقادیر ثبت‌شده در مراحل تکمیل‌شده سفارش را مبنای محاسبه قرار دهد و هرگونه ایجاد خودکار سفارش جدید یا ارجاع به مرحله &quot;تامین&quot; ممنوع است</span><span>.</span></p><p><span>-------------------------------------</span></p><p><span><br></span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">روند رسیدگی به کسری در کارتابل سرپرست</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">۱. رویداد ورود به کارتابل</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">پس از ایجاد کسری و ارجاع آن به سرپرست، پک مربوطه به‌صورت خودکار به کارتابل سرپرست انبار منتقل می‌شود.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">۲. نمایش در رابط کاربری (UI)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">پک در تب درحال بارگیری کارتابل سرپرست نمایش داده می‌شود.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">نکته بصری: این پک باید با رنگ قرمز متمایز شود تا وضعیت &quot;دارای کسری&quot; را به وضوح نشان دهد.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">۳. اقدام سرپرست (تایید کسری)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">سرپرست می‌تواند با انتخاب گزینه تایید کسری روی پک، فرآیند رسیدگی را آغاز کند. این اقدام منجر به دو رویداد می‌شود:</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">تغییر وضعیت: وضعیت پک به نیاز به تعیین تکلیف تغییر می‌کند.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">انتقال: پک به صفحه آماده بارگیری منتقل می‌شود.</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">۴. گزینه‌های تعیین تکلیف (در صفحه &quot;آماده بارگیری&quot;)</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">در صفحه جدید، سرپرست یکی از سه تصمیم نهایی زیر را برای پک اعمال می‌کند</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">بستن پرونده</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">ارجاع به تامین</span></p><p><span style=\"font-family:'Nunito Sans Bold', 'Nunito Sans', sans-serif;font-weight:700;color:#0E3C1C;\">بارگیری</span></p><p><span>--------------------------------------</span></p><p><span>کارت هایی که برای آنها کسری صادر میگردد(قرمز رنگ ها)، امکان لغو کسری و برگشت به حالت درحال بارگیری(زرد) و یا بارگیری نشده(سفید) را دارند. </span></p><p><span>------------------------------------</span></p><p><span>همه کارت ها با هر چیدمان بار در ماشین و بارکدخوانی یا تخصیص خودرو آپدیت میشوند. یعنی مانده و ردیف خودرو دائما درحال آپدیت هستند</span></p>",be="3",bf="1086a6e194c44b70981d6cda6aaa6eab",bg="تایید و ارجاع به سرپ",bh="<p><span>الگوریتم فعال‌سازی دکمه &quot;تایید و ارجاع&nbsp; به سرپرست&quot;</span></p><p><span>۱. شرط فعال‌سازی (Enable Condition)</span></p><p><span>دکمه &quot;ارسال به سرپرست&quot; برای یک پک فقط در صورتی فعال می‌شود که تمامی کارت‌های ریز اقلام آن پک در یکی از دو وضعیت زیر باشند:</span></p><p><span>سبز (تکمیل): COMPLETED</span></p><p><span>قرمز (دارای کسری): SHORTAGE_REGISTERED</span></p><p><span><br></span></p><p><span>نکته: اگر حتی یک کارت ریز قلم با وضعیتی غیر از این دو (مثلاً سفید یا زرد) وجود داشته باشد، دکمه باید غیرفعال (Disabled) باقی بماند.</span></p><p><span><br></span></p><p><span>۲. اقدام کاربر (اتمام بارگیری)</span></p><p><span>پس از فعال شدن دکمه، مسئول بارگیری می‌تواند با انتخاب آن، عملیات خود را نهایی کرده و پک را به عنوان &quot;اتمام بارگیری&quot; به سرپرست خود ارجاع دهد</span></p><p><span><br></span></p><p><span>فرآیند دریافت و نمایش پک در کارتابل سرپرست </span></p><p><span><br></span></p><p><span>پس از ارجاع پک توسط مسئول بارگیری، فرم کنترل و ارجاع بار در کارتابل سرپرست انبار به‌صورت زیر عمل می‌کند:</span></p><p><span>۱. محل نمایش</span></p><p><span>تمامی پک‌های ارجاع‌شده، در تب درحال بارگیری این فرم قرار می‌گیرند.</span></p><p><span>۲. منطق رنگ‌آمیزی و وضعیت</span></p><p><span>رنگ و وضعیت هر پک در این تب، بر اساس وجود یا عدم وجود کسری تعیین می‌شود:</span></p><p><span>رنگ سبز: تکمیل و بدون کسری</span></p><p><span>رنگ قرمز: دارای کسری</span></p><p><span>-------------------------------------</span></p><p><span><br></span></p>",bi="4",bj="245a7835aa8b46c59f3ba8f9336047c4",bk="تخصیص خودرو ",bl="<p><span>این گزینه زمانی فعال میگردد که حداقل یک کارت در حالت انتخاب باشد. با زدن این گزینه امکان انتخاب خودرو جهت کارت ها وجود دارد. یعنی هر کارت کالا در چه خودرویی قرار گرفته است</span></p>",bm="5",bn="2609803e618f4a93934d34b8a0aa35d1",bo="فیلتر اقلام آماده سا",bp="<p><span>&nbsp;مدیریت کارت‌های مرحله &quot;آماده‌سازی&quot; در صفحه بارگیری</span></p><p><span>۱. پیش‌زمینه منطقی</span></p><p><span>هر کارت کالا می‌تواند از یکی از این دو مسیر به مرحله بارگیری وارد شده باشد:</span></p><p><span>مرحله تسهیم (بدون آماده‌سازی): ROUTE_DIRECT</span></p><p><span>مرحله آماده‌سازی: ROUTE_PREPARATION</span></p><p><span><br></span></p><p><span>۲. ویژگی گزینه &quot;فیلتر کارت‌های آماده‌سازی&quot;</span></p><p><span>این گزینه در رابط کاربری (UI) صفحه بارگیری با هدف بهینه‌سازی فرآیند طراحی شده است.</span></p><p><span>عملکرد: با فعال‌سازی این گزینه (فیلتر)، فقط کارت‌هایی که از مسیر ROUTE_PREPARATION وارد شده‌اند در لیست نمایش داده می‌شوند. کارت‌های مسیر ROUTE_DIRECT موقتاً مخفی می‌شوند.</span></p><p><span><br></span></p><p><span>منطق کسب‌وکاری: از آنجایی که اقلام در مرحله آماده‌سازی قبلاً بارکدخوانی و سورت شده‌اند، بارگیری‌کننده می‌تواند بدون نیاز به اسکن مجدد بارکد، آنها را مستقیماً به داخل ماشین منتقل کند. این فیلتر باعث کاهش خطا و افزایش سرعت عملیات می‌شود.</span></p><p><span><br></span></p><p><span>۳. ویژگی گزینه &quot;انتخاب اقلام آماده‌سازی&quot;</span></p><p><span>این گزینه عملیاتی‌تر بوده و پس از اعمال فیلتر بالا استفاده می‌شود.</span></p><p><span>عملکرد: با انتخاب این گزینه، تمامی کارت‌های فیلترشده</span></p><p><span>&nbsp;(یعنی کارت‌های مسیر ROUTE_PREPARATION) به‌صورت خودکار در حالت انتخاب شده (Checked/Selected) قرار می‌گیرند.</span></p><p><span><br></span></p><p><span>گردش کار پس از انتخاب: کاربر (بارگیر) می‌تواند پس از مشاهده لیست انتخاب‌شده، با یک اقدام جمعی (مثلاً کلیک بر دکمه &quot;تأیید و ارسال به ماشین&quot;)، تمامی آن اقلام را به‌عنوان بارگیری‌شده ثبت کند.</span></p>",bq="6",br="fc8af4975f52458c9fc62f17fa5805e5",bs="Header 2",bt="<p><span>هر خودرو باید یک کد ردیف به خود بگیرد . ترتیب یا الویت خاصی بین خودرو ها نیست. صرفا جهت ایجاد ردیف خودرو برای&nbsp; کالاها می باشد</span></p>",bu="style",bv="baseStyle",bw="627587b6038d43cca051c114ac41ad32",bx="pageAlignment",by="center",bz="fill",bA="fillType",bB="solid",bC="color",bD=0xFFFFFFFF,bE="image",bF="imageAlignment",bG="near",bH="imageRepeat",bI="auto",bJ="favicon",bK="sketchFactor",bL="0",bM="colorStyle",bN="appliedColor",bO="fontName",bP="Applied Font",bQ="borderWidth",bR="borderVisibility",bS="borderFill",bT=0xFF